// Package validate contains small helpers shared by both services for
// checking incoming data. Each service decides WHICH rules apply; these
// functions just make the checks short and readable.
package validate

import (
	"fmt"
	"regexp"
	"strings"
)

// uuidPattern matches IDs generated by PostgreSQL's gen_random_uuid().
var uuidPattern = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)

// Errors collects every validation problem so the client sees all of them at
// once instead of fixing one field at a time.
type Errors []string

// Add records a problem.
func (e *Errors) Add(format string, args ...any) {
	*e = append(*e, fmt.Sprintf(format, args...))
}

// Empty reports whether no problems were found.
func (e Errors) Empty() bool { return len(e) == 0 }

// Error joins all problems into one message, e.g. "name is required; ...".
func (e Errors) Error() string { return strings.Join(e, "; ") }

// IsUUID checks that an ID has the correct UUID format.
func IsUUID(id string) bool { return uuidPattern.MatchString(id) }

// Required checks that a text field is not empty (ignoring spaces) and not too long.
func Required(errs *Errors, field, value string, maxLen int) {
	v := strings.TrimSpace(value)
	switch {
	case v == "":
		errs.Add("%s is required", field)
	case len(v) > maxLen:
		errs.Add("%s must be at most %d characters", field, maxLen)
	}
}

// Range checks that a number is between min and max (inclusive).
func Range(errs *Errors, field string, value, min, max int32) {
	if value < min || value > max {
		errs.Add("%s must be between %d and %d", field, min, max)
	}
}
